if [ -n "$PLAYER" ]; then
  case "$PLAYER" in
    mpg123) mpg123 -q "$TMPDIR/audio.mp3" >/dev/null 2>&1 & ;;
    ffplay) ffplay -nodisp -autoexit -loglevel quiet "$TMPDIR/audio.mp3" >/dev/null 2>&1 & ;;
    cvlc)   cvlc --play-and-exit --quiet "$TMPDIR/audio.mp3" >/dev/null 2>&1 & ;;
    mpv)    mpv --no-video --really-quiet "$TMPDIR/audio.mp3" >/dev/null 2>&1 & ;;
  esac
  AUDIO_PID=$!
else
  echo "(No se encontro mpg123/ffplay/cvlc/mpv -- solo animacion, sin audio)"
  sleep 1
fi

